theorem FiniteJetBound.fderiv {m : ℕ} {f : D → E} {s : Set D} {C : ℝ}
    (hf : FiniteJetBound (m + 1) f s C) :
    FiniteJetBound m (fderiv ℝ f) s C

theorem AllJetBound.fderiv {f : D → E} {s : Set D} {C : ℕ → ℝ}
    (hf : AllJetBound f s C) :
    AllJetBound (fderiv ℝ f) s (fun n => C (n + 1))

theorem inverseCoordinates_hasFDerivAt {a : ℝ} (ha : 0 < a) (ha1 : a < 1) {p : Point}
    (hp : p ∈ positiveTime) :
    HasFDerivAt (inverseCoordinates a) (inverseDifferential a (inverseCoordinates a p)) p

theorem inverseDifferential_contDiffAt {a : ℝ} {y : Point}
    (hy : 0 < y.1) (hs : scalarSlope a y.2.2 y.1 ≠ 0) :
    ContDiffAt ℝ ∞ (inverseDifferential a) y

theorem integral_eq_setIntegral {T : ℝ} {a : ℝ → ℝ} {f : ℝ → ℂ}
    (hs : tsupport a ⊆ Ioo (0 : ℝ) T) :
    (∫ t : ℝ, a t • f t) = ∫ t in Icc (0 : ℝ) T, a t • f t
